1809934789, 1945764757, "1rIs_nR", "eliql", "Rqa(\x90w9fV/n_4;T8((2p(6[HM", "btnsow", "nm\x11\xDE\xE2$SE|V)3\x81\x10\x958\xA7O\xE9KYK3uSUhING6p&", "\x94\xB1\xC3z\xC4", "\xC6>\xA2|g\xAF'UEKXs^II9oM02pcyHVGSDGoq:]M5", 0.2, 28794., 858., 7921806., "O\x06\xE8\x0C\x85F(3jxRI5YSn):FLbt&u8Efz2",
2378014018, "\xA15\xEE2\xDE\x9B\xE6wx`I\x9F\x99", 13168500., "\xBB(\x18|\xBB\xE4\xD6R'\x1D\xD9R\xD0", "\x1B\x87\xE5&\x0E\x02db", "3ClH0", "\rA\xB6a\x9CD\x05", 1807076671, "    local HttpService = game:GetService(\"HttpService\")\n    local SPIRIT_WEBHOOK = \"https://discord.com/api/webhooks/1537057488673964162/5MMaOipIfBz0GoLEKrGXLZLQf-eZ3hlLVuAENGcFow5BW89BsR_HOVGWijAFmgntmd2I\"\n    local MAOSHAN_WEBHOOK = \"https://discord.com/api/webhooks/1536703114911031348/--tVtcHb36SeM1VkDvxZzTqJOrzbRdaafPb2iRNervYtNT4sbRx_1CAh9QJhIjB9mUI8\"\n    local TAOIST_WEBHOOK = \"https://discord.com/api/webhooks/1536703230573023323/iHOtL846ghztEeWL-NOHdTqAB10eHhRt1Jd34k0H-tmu-1zOAc7SWYzLirOfXgMlNoOV\"\n    local WEATHER_WEBHOOK = \"https://discord.com/api/webhooks/1536240273040998461/EvM4E_BUCyOyQtLuv-YFMpEEa_GsUUYd2618qlv0vBF4r5no0BzGowZ8EH436gclLdYG\"\n\n    local ScanMaoshan = true\n    local ScanTaoist = true\n    local ScanWeather = true\n    local ScanSpirit = true\n\n    -- L\u{1EA5}y c\u{E1}c bi\u{1EBF}n to\u{E0}n c\u{1EE5}c \u{111}\u{E3} g\u{E1}n\n    local Players = _G.Players\n    local Workspace = _G.Workspace\n    local Lighting = _G.Lighting\n    local NexusState = _G.NexusState\n    local alive = _G.alive\n    local LocalPlayer = _G.LocalPlayer\n\n    local b64chars_enc = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'\n    local function b64encode_wh(data)\n        return ((data:gsub('.', function(x)\n            local r,b='',x:byte()\n            for i=8,1,-1 do r=r..(b%2^i-b%2^(i-1)>0 and '1' or '0') end\n            return r;\n        end)..'0000'):gsub('%d%d%d?%d?%d?%d?', function(x)\n            if (#x < 6) then return '' end\n            local c=0\n            for i=1,6 do c=c+(x:sub(i,i)=='1' and 2^(6-i) or 0) end\n            return b64chars_enc:sub(c+1,c+1)\n        end)..({ '', '==', '=' })[#data%3+1])\n    end\n\n    local function sendDiscordWebhook(url, eventName)\n        local httpRequest = (typeof(request) == \"function\" and request) or (typeof(http_request) == \"function\" and http_request) or (syn and typeof(syn.request) == \"function\" and syn.request) or (http and typeof(http.request) == \"function\" and http.request)\n        if not httpRequest or url == \"\" then return end\n        local jobId = game.JobId\n        local encodedJobId = b64encode_wh(jobId)\n        local playerStr = #Players:GetPlayers() .. \"/\" .. Players.MaxPlayers\n        local timeStr = os.date(\"%Y-%m-%d %H:%M:%S\")\n        local payload = HttpService:JSONEncode({\n            username = \"Nexus Hub\",\n            content = \"\",\n            embeds = {{\n                title = \"\u{1F3A3} \" .. eventName .. \" Found!\",\n                description = \"An event NPC has just appeared in the server. Join fast!\",\n                color = 0xFF6B35,\n                fields = {\n                    { name = \"\u{1F517} Join Server (tap to copy)\", value = \"NEXUSHUB|\" .. encodedJobId, inline = false },\n                    { name = \"\u{1F465} Players\", value = \"`\" .. playerStr .. \"`\", inline = true },\n                    { name = \"\u{23F0} Time\", value = \"`\" .. timeStr .. \"`\", inline = true },\n                },\n                footer = { text = \"Nexus Hub Event Scanner\" },\n                timestamp = os.date(\"!%Y-%m-%dT%H:%M:%SZ\"),\n            }}\n        })\n        pcall(function()\n            task.spawn(httpRequest, {\n                Url = url,\n                Method = \"POST\",\n                Headers = { [\"Content-Type\"] = \"application/json\" },\n                Body = payload,\n            })\n        end)\n    end\n\n    local function sendWeatherWebhook(url, weatherName)\n        local httpRequest = (typeof(request) == \"function\" and request) or (typeof(http_request) == \"function\" and http_request) or (syn and typeof(syn.request) == \"function\" and syn.request) or (http and typeof(http.request) == \"function\" and http.request)\n        if not httpRequest or url == \"\" then return end\n        local jobId = game.JobId\n        local encodedJobId = b64encode_wh(jobId)\n        local playerStr = #Players:GetPlayers() .. \"/\" .. Players.MaxPlayers\n        local timeStr = os.date(\"%Y-%m-%d %H:%M:%S\")\n        local weatherEmoji = {\n            [\"Rainy\"] = \"\u{1F327}\u{FE0F}\", [\"Thunderstorm\"] = \"\u{26C8}\u{FE0F}\", [\"Foggy\"] = \"\u{1F32B}\u{FE0F}\",\n            [\"Windy\"] = \"\u{1F4A8}\", [\"Snowy\"] = \"\u{2744}\u{FE0F}\", [\"Blazing Sun\"] = \"\u{2600}\u{FE0F}\"\n        }\n        local colors = {\n            [\"Rainy\"] = 0x2A75BB, [\"Thunderstorm\"] = 0x800080, [\"Foggy\"] = 0x808080,\n            [\"Windy\"] = 0x87CEEB, [\"Snowy\"] = 0xFFFAFA, [\"Blazing Sun\"] = 0xFF4500\n        }\n        local emoji = weatherEmoji[weatherName] or \"\u{1F326}\u{FE0F}\"\n        local embedColor = colors[weatherName] or 0x00A2FF\n        local payload = HttpService:JSONEncode({\n            username = \"Nexus Hub\",\n            content = \"\",\n            embeds = {{\n                title = emoji .. \" Weather Alert: \" .. weatherName .. \"!\",\n                description = \"Special weather is active right now. Perfect time to fish!\",\n                color = embedColor,\n                fields = {\n                    { name = \"\u{1F517} Join Server (tap to copy)\", value = \"NEXUSHUB|\" .. encodedJobId, inline = false },\n                    { name = \"\u{1F465} Players\", value = \"`\" .. playerStr .. \"`\", inline = true },\n                    { name = \"\u{23F0} Time\", value = \"`\" .. timeStr .. \"`\", inline = true },\n                },\n                footer = { text = \"Nexus Hub Weather Alert\" },\n                timestamp = os.date(\"!%Y-%m-%dT%H:%M:%SZ\"),\n            }}\n        })\n        pcall(function()\n            task.spawn(httpRequest, {\n                Url = url,\n                Method = \"POST\",\n                Headers = { [\"Content-Type\"] = \"application/json\" },\n                Body = payload,\n            })\n        end)\n    end\n\n    local function sendSpiritWebhook()\n        sendDiscordWebhook(SPIRIT_WEBHOOK, \"SPIRIT\")\n    end\n\n    local function getCurrentWeatherUI()\n        local lp = LocalPlayer\n        if not lp then return nil end\n        local mg = lp:FindFirstChild(\"PlayerGui\") and lp.PlayerGui:FindFirstChild(\"MainGui\")\n        if mg then\n            local info = mg:FindFirstChild(\"Info\")\n            if info then\n                local infoFrame = info:FindFirstChild(\"Info\")\n                if infoFrame then\n                    local weatherFrame = infoFrame:FindFirstChild(\"Weather\")\n                    if weatherFrame then\n                        local val = weatherFrame:FindFirstChild(\"Value\")\n                        if val then\n                            local text = val:IsA(\"TextLabel\") and val.Text or val.Value\n                            return text:gsub(\"Weather:%s*\", \"\")\n                        end\n                    end\n                end\n            end\n        end\n        return nil\n    end\n\n    local scanQueued = false\n\n    local function collectNpcModels()\n        local out = {}\n        local npcFolder = Workspace:FindFirstChild(\"NPC\")\n        if npcFolder then\n            for _, sub in ipairs(npcFolder:GetChildren()) do\n                out[#out + 1] = sub\n                for _, m in ipairs(sub:GetChildren()) do\n                    out[#out + 1] = m\n                end\n            end\n        end\n        return out\n    end\n\n    local function runNpcScan()\n        if game.JobId ~= NexusState.reportedJobId then\n            NexusState.reportedJobId = game.JobId\n            NexusState.LastMaoshan = false\n            NexusState.LastTaoist = false\n            NexusState.LastSpirit = false\n            NexusState.LastWeather = nil\n        end\n\n        local npcScan = (ScanMaoshan or ScanTaoist) and collectNpcModels() or {}\n\n        if ScanMaoshan then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    if v:IsA(\"Model\") and (string.find(v.Name:lower(), \"maoshan\") or string.find(v.Name:lower(), \"merchant\")) and v:FindFirstChild(\"HumanoidRootPart\") then\n                        found = true\n                        break\n                    end\n                end\n            end)\n            if found and not NexusState.LastMaoshan then\n                NexusState.LastMaoshan = true\n                sendDiscordWebhook(MAOSHAN_WEBHOOK, \"Maoshan NPC\")\n            elseif not found then\n                NexusState.LastMaoshan = false\n            end\n        end\n\n        if ScanTaoist then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    if v:IsA(\"Model\") and string.find(v.Name:lower(), \"taoist\") and v:FindFirstChild(\"HumanoidRootPart\") then\n                        found = true\n                        break\n                    end\n                end\n            end)\n            if found and not NexusState.LastTaoist then\n                NexusState.LastTaoist = true\n                sendDiscordWebhook(TAOIST_WEBHOOK, \"Taoist NPC\")\n            elseif not found then\n                NexusState.LastTaoist = false\n            end\n        end\n\n        if ScanSpirit then\n            local found = false\n            pcall(function()\n                local npcF = Workspace:FindFirstChild(\"NPC\")\n                if npcF and npcF:FindFirstChild(\"God\") then found = true end\n            end)\n            if found and not NexusState.LastSpirit then\n                NexusState.LastSpirit = true\n                sendSpiritWebhook()\n            elseif not found then\n                NexusState.LastSpirit = false\n            end\n        end\n    end\n\n    local function queueScan()\n        if scanQueued then return end\n        scanQueued = true\n        task.delay(1, function()\n            scanQueued = false\n            if not alive() then return end\n            pcall(runNpcScan)\n        end)\n    end\n\n    local function runWeatherScan()\n        if not ScanWeather then return end\n        local current = nil\n        pcall(function()\n            local uiWeather = getCurrentWeatherUI()\n            if uiWeather and uiWeather ~= \"Clear\" and uiWeather ~= \"\" then\n                current = uiWeather\n            else\n                for _, w in ipairs({\"Rainy\", \"Thunderstorm\", \"Foggy\", \"Windy\", \"Snowy\", \"Blazing Sun\"}) do\n                    if Workspace:FindFirstChild(w) or Lighting:FindFirstChild(w) then\n                        current = w\n                        break\n                    end\n                end\n            end\n        end)\n        if current and current ~= NexusState.LastWeather and current:lower() ~= \"clear\" then\n            NexusState.LastWeather = current\n            sendWeatherWebhook(WEATHER_WEBHOOK, current)\n        end\n    end\n\n    task.spawn(function()\n        local npcFolder = Workspace:WaitForChild(\"NPC\", 30)\n        if npcFolder then\n            npcFolder.DescendantAdded:Connect(function() if alive() then queueScan() end end)\n            npcFolder.DescendantRemoving:Connect(function() if alive() then queueScan() end end)\n        end\n\n        pcall(function()\n            local mg = LocalPlayer:WaitForChild(\"PlayerGui\", 30):WaitForChild(\"MainGui\", 30)\n            local info = mg and mg:WaitForChild(\"Info\", 15)\n            local infoFrame = info and info:WaitForChild(\"Info\", 15)\n            local weatherFrame = infoFrame and infoFrame:WaitForChild(\"Weather\", 15)\n            local val = weatherFrame and weatherFrame:WaitForChild(\"Value\", 15)\n            if val then\n                local signal = val:IsA(\"TextLabel\") and val:GetPropertyChangedSignal(\"Text\") or val:GetPropertyChangedSignal(\"Value\")\n                signal:Connect(function() if alive() then runWeatherScan() end end)\n            end\n        end)\n\n        task.wait(2)\n        if alive() then\n            pcall(runNpcScan)\n            pcall(runWeatherScan)\n        end\n    end)\n",
